<?php /** @var array $rows @var array $statuses @var string $selectedStatus @var bool $saved @var \Core\Security\Csrf $csrf @var string $basePath */ ?>
<?php if ($saved): ?><div class="flash-ok">Lead status updated.</div><?php endif; ?>
<div class="card"><form method="get" style="display:flex;gap:.5rem;align-items:end;flex-wrap:wrap"><label style="margin:0">Filter by status<select name="status"><option value="">All statuses</option><?php foreach ($statuses as $status): ?><option value="<?= e_attr($status) ?>"<?= $selectedStatus === $status ? ' selected' : '' ?>><?= e(ucwords(str_replace('-', ' ', $status))) ?></option><?php endforeach; ?></select></label><button class="btn small">Filter</button><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/catering/inquiries">Clear</a></form></div>
<?php if ($rows === []): ?><div class="card"><p>No catering inquiries match this filter.</p></div><?php endif; ?>
<?php foreach ($rows as $row): ?><article class="card"><div style="display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap"><div><span class="badge<?= $row['status'] === 'new' ? ' warn' : '' ?>"><?= e(ucwords(str_replace('-', ' ', $row['status']))) ?></span><h2 style="margin:.5rem 0 .25rem"><?= e($row['name']) ?> · <?= e($row['event_type'] ?: ucfirst($row['kind'])) ?></h2><p class="muted"><?= e($row['email']) ?><?= $row['phone'] ? ' · ' . e($row['phone']) : '' ?> · received <?= e($row['created_at']) ?></p></div><form method="post" style="display:flex;gap:.5rem;align-items:end"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><label style="margin:0">Status<select name="status"><?php foreach ($statuses as $status): ?><option value="<?= e_attr($status) ?>"<?= $row['status'] === $status ? ' selected' : '' ?>><?= e(ucwords(str_replace('-', ' ', $status))) ?></option><?php endforeach; ?></select></label><button class="btn small">Update</button></form></div><table><tbody><tr><th>Event date</th><td><?= e($row['event_date'] ?: 'Not provided') ?> <?= e($row['event_time']) ?></td><th>Guests</th><td><?= $row['guest_count'] ? (int) $row['guest_count'] : 'Not provided' ?></td></tr><tr><th>Venue</th><td><?= e($row['venue'] ?: 'Not provided') ?></td><th>Service</th><td><?= e($row['service_style'] ?: 'Not provided') ?></td></tr><tr><th>Menu</th><td><?= e($row['menu_interest'] ?: 'Open') ?></td><th>Budget</th><td><?= e($row['budget'] ?: 'Not provided') ?></td></tr></tbody></table><?php if ($row['dietary']): ?><p><strong>Dietary needs:</strong> <?= nl2br(e($row['dietary'])) ?></p><?php endif; ?><?php if ($row['message']): ?><p><strong>Notes:</strong><br><?= nl2br(e($row['message'])) ?></p><?php endif; ?></article><?php endforeach; ?>
